{"code": "from decimal import Decimal, localcontext, ROUND_DOWN, ROUND_HALF_UP


def _q(value, scale, rounding):
    exp = Decimal(1).scaleb(-scale)
    with localcontext() as ctx:
        ctx.prec = 34
        r = Decimal(value).quantize(exp, rounding=rounding)
        if r == 0:
            r = abs(r)
    return r


def _s(d):
    return format(d, 'f')


def _dec(v):
    if isinstance(v, Decimal):
        return v
    return Decimal(str(v))


def run(input: dict):
    monto = _q(_dec(input['monto']), 2, ROUND_DOWN)
    tasa_anual = _q(_dec(input['tasa_anual']), 2, ROUND_DOWN)
    plazo = int(input['plazo'])

    # BR-001
    if monto <= 0:
        return {'error': {'code': 'E01', 'message': 'Monto inválido: debe ser mayor que cero'}}
    # BR-002
    if plazo < 1 or plazo > 360:
        return {'error': {'code': 'E02', 'message': 'Plazo inválido: debe estar entre 1 y 360 meses'}}

    with localcontext() as ctx:
        ctx.prec = 34

        # BR-003
        if monto >= Decimal('50000000'):
            tasa_anual = _q(tasa_anual - Decimal('0.50'), 2, ROUND_DOWN)

        # BR-004
        tasa_mes = _q(tasa_anual / Decimal(1200), 8, ROUND_DOWN)

        # BR-005
        factor = _q((Decimal(1) + tasa_mes) ** plazo, 8, ROUND_DOWN)

        # BR-006
        denom = factor - Decimal(1)
        if denom == 0:
            return {'error': {'code': 'DIV0', 'message': 'División entre cero en el cálculo de la cuota'}}
        cuota = _q(monto * tasa_mes * factor / denom, 2, ROUND_HALF_UP)

        # BR-009 / BR-007 / BR-008
        saldo = monto
        rows = []
        for periodo in range(1, plazo + 1):
            interes = _q(saldo * tasa_mes, 2, ROUND_DOWN)
            capital = _q(cuota - interes, 2, ROUND_DOWN)
            saldo = _q(saldo - capital, 2, ROUND_DOWN)
            rows.append({
                'periodo': periodo,
                'cuota': _s(cuota),
                'interes': _s(interes),
                'capital': _s(capital),
                'saldo': _s(saldo),
                'codigo_error': '',
            })
    return rows
